/** 原生红月状态的有限审计转换，不采用任意 live 库存。 */
export function commitDemonRedMoonTransition(
  world: World,
  actorId: number,
  kind: "blast" | "exile" | "expire",
  day: number,
): boolean {
  const b = bindings.get(world),
    p = b?.players.get(actorId);
  const n = kind === "expire" ? b?.active : b?.nights.get(day);
  if (
    !b ||
    !p ||
    !n ||
    n.day !== day ||
    !validBinding(b) ||
    String(p.kind) !== RED_MOON_ROLE ||
    ![...b.players.values()].every((player) => originalLife(player, world)) ||
    !privateAuditCurrent(b, p)
  )
    return false;
  const state = getRedMoonState(p.role);
  if (!state || !writableDemonFields(state, ["blastDay", "exileDay", "expirySettled"]))
    return false;
  // 本族编码函数只消费已捕获的影子；解析查找先于 audit 字段读取，原体／夜权限仍留在这里。
  const original = readRedMoonShadow(() => p.auditPrivateJson);
  const next = copyRedMoonPayload(state);
  if (kind === "expire") {
    if (n.closed || !n.frozen || state.exileDay !== day - 1 || state.expirySettled) return false;
    next.expirySettled = true;
  } else {
    if (
      b.active ||
      !n.closed ||
      !n.frozen ||
      [...b.nights.keys()].some((d) => d > day) ||
      !originalLife(p, world, true) ||
      state.blastDay !== null ||
      state.exileDay !== null
    )
      return false;
    const wolves = [...b.players.values()].filter(
      (player) => player.camp === Camp.Wolf && originalLife(player, world, true),
    ).length;
    if (kind === "blast") {
      if (wolves === 1 && state.lastWolfBlastPolicy === "forbidden") return false;
      next.blastDay = day;
    } else if (kind === "exile") {
      if (wolves !== 1) return false;
      next.exileDay = day;
    } else return false;
  }
  const expected = encodeRedMoonShadow(original, next);
  // 三写只归本族 slot；完整容器验收和 audit 最终更新保持原点，后续失败不撤销先前字段。
  writeRedMoonTransition(state, next);
  if (demonJson(p.privateState) !== expected) throw new Error("red_moon_state_commit_failed");
  p.auditPrivateJson = expected;
  return true;
}

/** 原红月自爆只抑制紧接的下一夜好人行动。 */
export function demonRedMoonNightSealed(world: World, day: number): boolean {
  const b = bindings.get(world);
  if (!b) return false;
  const p = [...b.players.values()].find((p) => String(p.kind) === RED_MOON_ROLE);
  if (!p) return false;
  if (!validBinding(b) || ![...b.players.values()].every((p) => originalLife(p, world)))
    throw new Error("red_moon_original_state_revoked");
  const state = getRedMoonState(p.role);
  if (!state || !privateAuditCurrent(b, p)) throw new Error("red_moon_original_state_revoked");
  const sealed = Number.isSafeInteger(day) && day > 1 && state.blastDay === day - 1;
  if (sealed && originalLife(p, world, true)) throw new Error("red_moon_blast_death_unsettled");
  return sealed;
}

/** 有限板子的白痴翻牌时，同时保留私有库存与公开票权审计。 */
export function commitDemonIdiotReveal(world: World, actorId: number): boolean {
  const b = bindings.get(world);
  if (!b) return false;
  const p = b.players.get(actorId),
    cp = p?.checkpoint;
  if (
    !p ||
    !cp ||
    p.kind !== Role.Idiot ||
    !validBinding(b) ||
    !originalLife(p, world, true) ||
    !privateAuditCurrent(b, p) ||
    world.getComponent(actorId, COMPONENT.VotingRight) !== cp.vote ||
    demonVoteJson(cp.vote) !== cp.voteJson ||
    !writableDemonFields(p.privateState, ["idiot"]) ||
    !writableDemonFields(cp.vote, ["canVote", "weight"])
  )
    throw new Error("demon_hunter_idiot_state_revoked");
  const before = ownDemonData(p.privateState, "idiot");
  if (!exactDemonData(before, ["revealed"]) || ownDemonData(before, "revealed") !== false)
    throw new Error("demon_hunter_idiot_state_revoked");
  // 消耗翻牌前先验证后续同步警徽交接。
  openDemonBadgeFrame(world);
  const next = { revealed: true };
  const original = JSON.parse(p.auditPrivateJson) as Record<string, unknown>;
  const expectedPrivate = JSON.stringify({ ...original, idiot: next });
  const expectedVote = JSON.stringify({ ...JSON.parse(cp.voteJson), canVote: false, weight: 0 });
  (p.privateState as { idiot: typeof next }).idiot = next;
  (cp.vote as VotingRightComponent).canVote = false;
  (cp.vote as VotingRightComponent).weight = 0;
  if (demonJson(p.privateState) !== expectedPrivate || demonVoteJson(cp.vote) !== expectedVote)
    throw new Error("demon_hunter_idiot_commit_failed");
  p.privateRefs = p.privateRefs.map(
    ([key, value]) => [key, key === "idiot" ? next : value] as const,
  );
  p.inventoryRefs = p.inventoryRefs.map(
    ([path, value]) => [path, path.length === 1 && path[0] === "idiot" ? next : value] as const,
  );
  p.auditPrivateJson = expectedPrivate;
  cp.voteJson = expectedVote;
  return true;
}

/** 在任何旧状态 getter 可执行前读取已提交的白痴状态。 */
export function demonIdiotRevealed(world: World, actorId: number): boolean | null {
  const b = bindings.get(world);
  if (!b) return null;
  const p = b.players.get(actorId),
    cp = p?.checkpoint;
  if (
    !p ||
    !cp ||
    p.kind !== Role.Idiot ||
    !validBinding(b) ||
    !originalLife(p, world, true) ||
    !privateAuditCurrent(b, p) ||
    world.getComponent(actorId, COMPONENT.VotingRight) !== cp.vote ||
    demonVoteJson(cp.vote) !== cp.voteJson
  )
    throw new Error("demon_hunter_idiot_state_revoked");
  const state = ownDemonData(p.privateState, "idiot");
  const revealed = ownDemonData(state, "revealed");
  if (!exactDemonData(state, ["revealed"]) || typeof revealed !== "boolean")
    throw new Error("demon_hunter_idiot_state_revoked");
  return revealed;
}

/** 有限板子当前日只由最近已结算的夜产生。 */
export function demonRedMoonDay(world: World, actorId: number): number | null {
  const b = bindings.get(world),
    p = b?.players.get(actorId);
  if (!b || !p || String(p.kind) !== RED_MOON_ROLE) return null;
  demonHunterCheckpointPlayers(world, true);
  if (b.active || !originalLife(p, world, true)) return null;
  const day = [...b.nights.keys()].at(-1);
  const n = day === undefined ? null : b.nights.get(day);
  return n?.closed && n.frozen ? n.day : null;
}
export function demonRedMoonCanBlast(world: World, actorId: number): boolean {
  if (demonRedMoonDay(world, actorId) === null) return false;
  const b = bindings.get(world)!,
    p = b.players.get(actorId)!;
  const state = getRedMoonState(p.role);
  if (!state || state.blastDay !== null || state.exileDay !== null) return false;
  const wolves = [...b.players.values()].filter(
    (player) => player.camp === Camp.Wolf && originalLife(player, world, true),
  ).length;
  return wolves > 1 || state.lastWolfBlastPolicy === "ends_game";
}
export function commitDemonRedMoonBlast(
  world: World,
  actorId: number,
): { day: number; sealsNight: boolean } | null {
  const day = demonRedMoonDay(world, actorId);
  if (day === null || !demonRedMoonCanBlast(world, actorId)) return null;
  const b = bindings.get(world)!;
  const wolves = [...b.players.values()].filter(
    (player) => player.camp === Camp.Wolf && originalLife(player, world, true),
  ).length;
  if (!commitDemonRedMoonTransition(world, actorId, "blast", day)) return null;
  return { day, sealsNight: wolves > 1 };
}

/** 被延后的存活最后一狼只在普通来源已结算后到期。 */
export function demonRedMoonExpiry(world: World, day: number): number | null {
  const b = bindings.get(world);
  if (!b) return null;
  const p = [...b.players.values()].find((player) => String(player.kind) === RED_MOON_ROLE);
  if (!p) return null;
  demonHunterCheckpointPlayers(world, true);
  const n = b.active;
  if (!n || n.day !== day || n.closed || !n.frozen)
    throw new Error("red_moon_expiry_phase_invalid");
  const state = getRedMoonState(p.role);
  if (!state) throw new Error("red_moon_original_state_revoked");
  return state.exileDay === day - 1 && !state.expirySettled && originalLife(p, world, true)
    ? p.id
    : null;
}

export function isRedMoonBoard(world: World): boolean {
  const b = bindings.get(world);
  if (!b || ![...b.players.values()].some((p) => p.kind === Role.RedMoonApostle)) return false;
  if (!validBinding(b)) throw new Error("red_moon_original_state_revoked");
  return true;
}

/**
 * Owns Idiot state data and access to its existing private-state slot.
 * Inputs are the role component and native state; outputs retain the exact stored object, including assignment-before-return behavior.
 * Existing mutation commands, lifecycle validation, player projection and checkpoint
 * encoding keep their current responsibilities. This leaf creates no mirror state,
 * consumes no resource and does not decide whether a request is authorized.
 * Pure payload/read data structures belong to the neutral role-state data owner;
 * this leaf retains original live references and concrete installation/commit operations.
 */
import type { IdiotState, IdiotReadState } from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";

export function setIdiotState(roleComp: RoleComponent, state: IdiotState): IdiotReadState {
  (roleComp.privateState as { idiot: IdiotState })["idiot"] = state;
  return state;
}

export function getIdiotState(roleComp: RoleComponent): IdiotReadState | undefined {
  return (roleComp.privateState as { readonly idiot?: unknown })["idiot"] as
    IdiotReadState | undefined;
}

/**
 * Owns sheriff badge assignment, vote-weight updates and transfer/destruction commitment. Inputs
 * are current badge bodies and eligible successors; outputs preserve badge events, sheriff
 * identity and weights. A destroyed badge does not silently restore itself through a replacement
 * component.
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { openDemonBadgeFrame, assertDemonBadgeReadable } from "../roles/demon_hunter/authority";
import { weddingBadgeSwallowed } from "../roles/ghost_bride/authority";
/** 文件说明：警徽流转、销毁与授予逻辑。 */
import { AliveComponent } from "../../../core/domain/components/alive";
import { BadgeComponent } from "../../../core/domain/components/badge";
import { COMPONENT } from "../../../core/domain/components/names";
import { VotingRightComponent } from "../../../core/domain/components/voting_right";
import { IdentityComponent } from "../../../core/domain/entities/player";
import { EntityId, GameEvent } from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { canBeSheriff } from "../common/participation";
import type { RoleCatalog } from "../roles/catalog";

const SHERIFF_VOTE_WEIGHT = 1.5;

export interface SheriffBadgeTransferResult {
  fromId: EntityId;
  toId: EntityId | null;
  destroyed: boolean;
}

export function assignSheriff(
  world: World,
  sheriffId: EntityId,
  config?: ReadonlyBoardConfig,
  catalog?: RoleCatalog,
): boolean {
  assertDemonBadgeReadable(world);
  if (weddingBadgeSwallowed(world) || !canBeSheriff(world, sheriffId, catalog)) return false;
  const frame = openDemonBadgeFrame(world);
  const weight = config?.sheriff?.voteWeight ?? SHERIFF_VOTE_WEIGHT;
  for (const id of world.getAliveEntityIds()) {
    const badge = world.getComponent(id, COMPONENT.Badge);
    if (badge) {
      badge.isSheriff = id === sheriffId;
      badge.destroyed = false;
      badge.voteWeight = weight;
      if (config?.sheriff?.badgePolicy === "awa_holder_choice_v1")
        badge.handoffPolicy = "awa_holder_choice_v1";
      else delete badge.handoffPolicy;
    }
    const voting = world.getComponent(id, COMPONENT.VotingRight);
    if (voting?.canVote) voting.weight = id === sheriffId ? weight : 1;
  }
  frame?.commit({
    kind: "assign",
    sheriffId,
    weight,
    policy:
      config?.sheriff?.badgePolicy === "awa_holder_choice_v1" ? "awa_holder_choice_v1" : undefined,
  });
  return true;
}

export function transferOrDestroySheriffBadge(
  world: World,
  fromId: EntityId,
  reason: string,
  events: GameEvent[],
  catalog?: RoleCatalog,
): SheriffBadgeTransferResult | null {
  assertDemonBadgeReadable(world);
  const badge = world.getComponent(fromId, COMPONENT.Badge);
  if (!badge?.isSheriff || badge.destroyed) return null;
  return commitSheriffBadgeChoice(
    world,
    fromId,
    reason,
    events,
    badge.handoffPolicy === "awa_holder_choice_v1"
      ? null
      : pickNextSheriffCandidate(world, fromId, catalog),
    catalog,
  );
}

/** Commits only a currently eligible target; a rejected choice destroys the held badge. */
export function commitSheriffBadgeChoice(
  world: World,
  fromId: EntityId,
  reason: string,
  events: GameEvent[],
  targetId: EntityId | null,
  catalog?: RoleCatalog,
): SheriffBadgeTransferResult | null {
  assertDemonBadgeReadable(world);
  const badge = world.getComponent(fromId, COMPONENT.Badge);
  if (!badge?.isSheriff || badge.destroyed) return null;
  const frame = openDemonBadgeFrame(world);
  const weight = badge.voteWeight ?? SHERIFF_VOTE_WEIGHT;
  const policy = badge.handoffPolicy;
  const nextSheriffId =
    targetId !== null && badgeSuccessorEligible(world, fromId, targetId, catalog) ? targetId : null;
  badge.isSheriff = false;
  badge.destroyed = true;
  resetVotingWeight(world, fromId);
  if (nextSheriffId === null) {
    frame?.commit({ kind: "handoff", fromId, toId: null, weight, policy });
    events.push({
      timestamp: Date.now(),
      type: "sheriff_badge_destroyed",
      payload: { targetId: fromId, reason },
    });
    return { fromId, toId: null, destroyed: true };
  }
  const nextBadge = world.getComponent(nextSheriffId, COMPONENT.Badge);
  if (nextBadge) {
    nextBadge.isSheriff = true;
    nextBadge.destroyed = false;
    nextBadge.voteWeight = weight;
    if (policy) nextBadge.handoffPolicy = policy;
    else delete nextBadge.handoffPolicy;
  }
  const nextVoting = world.getComponent(nextSheriffId, COMPONENT.VotingRight);
  if (nextVoting) nextVoting.weight = weight;
  frame?.commit({ kind: "handoff", fromId, toId: nextSheriffId, weight, policy });
  events.push({
    timestamp: Date.now(),
    type: "sheriff_badge_transferred",
    payload: { fromId, toId: nextSheriffId, reason },
  });
  return { fromId, toId: nextSheriffId, destroyed: false };
}

function resetVotingWeight(world: World, entityId: EntityId): void {
  const voting = world.getComponent(entityId, COMPONENT.VotingRight);
  if (voting) voting.weight = voting.canVote ? 1 : 0;
}

export function badgeSuccessorEligible(
  world: World,
  fromId: EntityId,
  id: EntityId,
  catalog?: RoleCatalog,
): boolean {
  assertDemonBadgeReadable(world);
  return (
    id !== fromId &&
    canBeSheriff(world, id, catalog) &&
    world.getComponent(id, COMPONENT.Alive)?.alive === true &&
    world.getComponent(id, COMPONENT.VotingRight)?.canVote === true &&
    world.getComponent(id, COMPONENT.Badge)?.destroyed === false
  );
}

function pickNextSheriffCandidate(
  world: World,
  fromId: EntityId,
  catalog?: RoleCatalog,
): EntityId | null {
  assertDemonBadgeReadable(world);
  const candidates = world
    .getAliveEntityIds()
    .filter((id) => badgeSuccessorEligible(world, fromId, id, catalog));
  candidates.sort((a, b) => {
    const aSeat = world.getComponent(a, COMPONENT.Identity)?.seat ?? a;
    const bSeat = world.getComponent(b, COMPONENT.Identity)?.seat ?? b;
    return aSeat - bSeat;
  });
  return candidates[0] ?? null;
}

export function findSheriffId(world: World, catalog?: RoleCatalog): EntityId | null {
  assertDemonBadgeReadable(world);
  return (
    world.getAliveEntityIds().find((id) => {
      const badge = world.getComponent(id, COMPONENT.Badge);
      return (
        badge?.isSheriff === true && badge.destroyed === false && canBeSheriff(world, id, catalog)
      );
    }) ?? null
  );
}

export function assignInitialSheriff(
  world: World,
  config: ReadonlyBoardConfig,
  playerIds: EntityId[],
): void {
  if (!config.enableSheriff || config.initialSheriffSeat === undefined) return;
  const sheriffId = playerIds.find(
    (id) => world.getComponent(id, COMPONENT.Identity)?.seat === config.initialSheriffSeat,
  );
  if (sheriffId !== undefined) assignSheriff(world, sheriffId, config);
}

/**
 * 负责原放逐／死亡动作分发，以及独立于可替换晚 hook 的必需整波贡献装配。
 * 输入为原 World、原名单／原因、日期／阶段和事件；输出保留免死结果或额外死亡提案。
 * 已提交整波贡献在实际标死之后、梦记录及遗言之前同步执行；榜样首次死亡由野孩子唯一绑定 owner 提交。
 * 这里不修改 Alive、选择阶段或回滚贡献已写事实；首失败原样传播，停止后续贡献并保留已付／已提交前缀。
 */
import {
  EntityId,
  GameEvent,
  type DeathSources,
  type Phase,
  type DeathShotSelection,
} from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";
import type { NightLifeScope } from "../../../core/domain/night_effects";
import type { DeathWaveContribution } from "./death-wave-contribution";
import { giftGunDeathHook } from "../roles/gift_gun_death_hook";
import { resolveWildChildDeathWave } from "../roles/wild_child/ports";

/** 已完成本批 Alive 提交后的具名扩展时点；不是可追加死亡或选择枪的晚 deathHook。 */
export type CommittedDeathWaveHook = (
  world: World,
  deadIds: readonly EntityId[],
  deathSources: DeathSources,
  day: number,
  phase: Phase,
  events: GameEvent[],
) => void;

/** 真实必需整波贡献装配；不属于调用方可替换的 votedOut／晚 deathHook 列表。 */
export function createCommittedDeathWaveContributions(): readonly CommittedDeathWaveHook[] {
  return [resolveWildChildDeathWave];
}

/** 放逐钩子返回结果。 */
export interface VotedOutResult {
  prevented: boolean;
  removed: EntityId[];
  reason: string;
}

/** 死亡钩子聚合结果。 */
export interface DeathHookResult {
  extraDeaths: EntityId[];
  extraDeathSources: DeathSources;
  nightEffectTargets?: EntityId[];
  pendingShots?: Array<{
    targetScope: NightLifeScope;
    event: GameEvent;
    isCurrent?: () => boolean;
  }>;
  /** 每 hook 同步消费的本族运行贡献；具体绑定／回执不属于通用结果。 */
  deathWaveContributions?: DeathWaveContribution[];
}
export interface DeathHookContext {
  readonly deathOriginPhase?: Phase;
  nativeHunterShotTargets?: ReadonlySet<EntityId>;
  day?: number;
  deferShotCommit?: boolean;
  nightEffect: boolean;
  blocksNightShot(targetId: EntityId): boolean;
  blocksNightCharm?: (targetId: EntityId) => boolean;
  eligibleDead?: ReadonlySet<EntityId>;
  isCurrent?: () => boolean;
}

/** 放逐钩子函数签名。 */
export type VotedOutHook = (
  world: World,
  targetId: EntityId,
  events: GameEvent[],
) => VotedOutResult | null;

/** 死亡钩子函数签名。 */
export type DeathHook = (
  world: World,
  deadIds: EntityId[],
  deathSources: DeathSources,
  chooseDeathShot: (actorId: EntityId, abilityId?: string) => Promise<DeathShotSelection>,
  events: GameEvent[],
  context?: DeathHookContext,
) => Promise<DeathHookResult>;

function buildDefaultVotedOutHooks(): VotedOutHook[] {
  return getDefaultRoleCatalog()
    .allRuntime()
    .map(({ runtime }) => runtime.votedOutHook)
    .filter((hook): hook is VotedOutHook => Boolean(hook));
}

function buildDefaultDeathHooks(): DeathHook[] {
  return getDefaultRoleCatalog()
    .allRuntime()
    .map(({ runtime }) => runtime.deathHook)
    .filter((hook): hook is DeathHook => Boolean(hook))
    .concat(giftGunDeathHook);
}

/** 钩子注册表：负责分发放逐钩子与死亡钩子。 */
export class HookRegistry {
  constructor(
    private readonly votedOutHooks: VotedOutHook[] = buildDefaultVotedOutHooks(),
    private readonly deathHooks: DeathHook[] = buildDefaultDeathHooks(),
  ) {}

  onVotedOut(world: World, targetId: EntityId, events: GameEvent[]): VotedOutResult | null {
    for (const hook of this.votedOutHooks) {
      const result = hook(world, targetId, events);
      if (result) {
        return result;
      }
    }
    return null;
  }

  async onDeath(
    world: World,
    deadIds: EntityId[],
    deathSources: DeathSources,
    chooseDeathShot: (actorId: EntityId, abilityId?: string) => Promise<DeathShotSelection>,
    events: GameEvent[],
    commitAdditionalDeaths?: (result: DeathHookResult) => void,
    context?: DeathHookContext,
  ): Promise<DeathHookResult> {
    const aggregated: DeathHookResult = {
      extraDeaths: [],
      extraDeathSources: {},
    };
    for (const hook of this.deathHooks) {
      if (context?.isCurrent && !context.isCurrent()) break;
      const result = await hook(world, deadIds, deathSources, chooseDeathShot, events, context);
      commitAdditionalDeaths?.(result);
      aggregated.extraDeaths.push(...result.extraDeaths);
      if (result.nightEffectTargets?.length)
        (aggregated.nightEffectTargets ??= []).push(...result.nightEffectTargets);
      if (result.pendingShots?.length)
        (aggregated.pendingShots ??= []).push(...result.pendingShots);
      if (result.deathWaveContributions?.length)
        (aggregated.deathWaveContributions ??= []).push(...result.deathWaveContributions);
      for (const [id, marks] of Object.entries(result.extraDeathSources)) {
        aggregated.extraDeathSources[Number(id)] = [
          ...new Set([...(aggregated.extraDeathSources[Number(id)] ?? []), ...marks]),
        ];
      }
    }
    return aggregated;
  }
}

let defaultRegistry: HookRegistry | null = null;

/** 获取默认钩子注册表实例。 */
export function getDefaultHookRegistry(): HookRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new HookRegistry();
  }
  return defaultRegistry;
}

/**
 * 构造蚀日者有界机制测试的显式 World、组件、Catalog 与初始座位。输入为原配置、组件及调用方字段，输出为原 fixture；手写断言和身份快照由测试持有，不运行完整对局、传输或生产规则验证器。
 */
import {
  createAliveComponent,
  createBadgeComponent,
  createCampComponent,
  createStatusMarksComponent,
  createVotingRightComponent,
} from "../../../../../src/game/observation/component-presentation";
import type { LastWolfBlastPolicy } from "@ai-werewolf-arena/game-contract";
import { World } from "../../../../../src/core/domain/world";
import { Role } from "../../../../../src/core/domain/identity";
import { COMPONENT } from "../../../../../src/core/domain/components/names";
import { createRoleComponent } from "../../../../../src/game/observation/role-presentation";

import { createVictoryComponent } from "../../../../../src/core/domain/components/victory";
import { createIdentityComponent } from "../../../../../src/core/domain/entities/player";
import { installInitialRoster } from "../../../../../src/core/domain/initial_roster";
import { RoleCatalog } from "../../../../../src/game/mechanisms/roles/catalog";
import {
  getDefaultRoleCatalog,
  getDefaultRoleContributions,
  createRoleCatalog,
} from "../../../../../src/game/mechanisms/roles/role-catalog-assembly";
import { RED_MOON_ROLE_PROFILE } from "../../../../../src/game/mechanisms/roles/red_moon_apostle/profile";
import { installDemonHunter } from "../../../../../src/game/mechanisms/roles/demon_hunter/authority";
import { redMoonTwelveConfig } from "../../../../../src/runtime/scenarios/red_moon_twelve";

export function redMoonCandidateWorld(policy: LastWolfBlastPolicy = "ends_game") {
  const world = new World();
  const config = structuredClone(redMoonTwelveConfig);
  config.redMoon!.lastWolfBlastPolicy = policy;
  const catalog = createRoleCatalog({
    contributions: [
      ...getDefaultRoleContributions().filter(
        (p) => String(p.metadata.role) !== "red_moon_apostle",
      ),
      RED_MOON_ROLE_PROFILE,
    ],
  });
  const roles = config.roleSetups.flatMap((row) => Array<Role>(row.count).fill(row.role));
  const ids = roles.map((kind, i) => {
    const id = world.createEntity();
    const role = createRoleComponent(kind, catalog.getCamp(kind), world.locale);
    catalog.applyRuntime(role, { boardConfig: config, locale: world.locale, world });
    world.addComponent(id, COMPONENT.Identity, createIdentityComponent(id, i + 1, "player-" + id));
    world.addComponent(id, COMPONENT.Role, role);
    world.addComponent(id, COMPONENT.Camp, createCampComponent(role.camp, world.locale));
    world.addComponent(
      id,
      COMPONENT.Victory,
      createVictoryComponent([{ kind: "faction", faction: role.camp }]),
    );
    world.addComponent(id, COMPONENT.Alive, createAliveComponent(true, world.locale));
    world.addComponent(id, COMPONENT.StatusMarks, createStatusMarksComponent(world.locale));
    world.addComponent(
      id,
      COMPONENT.VotingRight,
      createVotingRightComponent(1, true, world.locale),
    );
    world.addComponent(id, COMPONENT.Badge, createBadgeComponent(false, false, world.locale));
    return id;
  });
  installInitialRoster(world);
  installDemonHunter(world, config);
  return { world, config, ids, catalog };
}
